// Patches the android/ folder generated by `flutter create`:
// permissions, the background monitor service, boot receiver, Android Auto
// package visibility, car-app library and the native Kotlin sources.
// Safe to run multiple times:  dart run tool/patch_platforms.dart
import 'dart:io';

void patch(String path, String Function(String) change) {
  final f = File(path);
  if (!f.existsSync()) return;
  final before = f.readAsStringSync();
  final after = change(before);
  if (after != before) {
    f.writeAsStringSync(after);
    stdout.writeln('patched $path');
  }
}

const perms = [
  'android.permission.ACCESS_NETWORK_STATE',
  'android.permission.ACCESS_WIFI_STATE',
  'android.permission.CHANGE_WIFI_STATE',
  'android.permission.ACCESS_FINE_LOCATION',
  'android.permission.ACCESS_COARSE_LOCATION',
  'android.permission.ACCESS_BACKGROUND_LOCATION',
  'android.permission.BLUETOOTH_CONNECT',
  'android.permission.POST_NOTIFICATIONS',
  'android.permission.FOREGROUND_SERVICE',
  'android.permission.FOREGROUND_SERVICE_CONNECTED_DEVICE',
  'android.permission.RECEIVE_BOOT_COMPLETED',
  'android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS',
];

const legacy = '''
    <uses-permission android:name="android.permission.BLUETOOTH" android:maxSdkVersion="30"/>
    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28"/>
    <uses-permission android:name="android.permission.READ_LOGS" tools:ignore="ProtectedPermissions"/>
''';

const components = '''
        <service
            android:name=".MonitorService"
            android:exported="false"
            android:foregroundServiceType="connectedDevice"/>
        <receiver android:name=".BootReceiver" android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
''';

void main() {
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    if (!s.contains('xmlns:tools')) {
      s = s.replaceFirst('<manifest ', '<manifest xmlns:tools="http://schemas.android.com/tools" ');
    }
    final block = perms
        .where((p) => !s.contains('"$p"'))
        .map((p) => '    <uses-permission android:name="$p"/>\n')
        .join();
    final m = RegExp(r'<manifest[^>]*>\s*\n').firstMatch(s);
    if (m != null) {
      final extra = s.contains('READ_LOGS') ? '' : legacy;
      s = s.replaceRange(m.end, m.end, block + extra);
    }
    if (!s.contains('.MonitorService')) {
      s = s.replaceFirst('    </application>', '$components    </application>');
    }
    if (!s.contains('com.google.android.projection.gearhead')) {
      const pkg = '        <package android:name="com.google.android.projection.gearhead"/>\n';
      if (s.contains('<queries>')) {
        s = s.replaceFirst('<queries>\n', '<queries>\n$pkg');
      } else {
        s = s.replaceFirst('</manifest>', '    <queries>\n$pkg    </queries>\n</manifest>');
      }
    }
    return s.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="Nauto"');
  });

  patch('android/app/build.gradle.kts', (s) {
    s = s.replaceFirst(RegExp(r'minSdk = [^\n]+'), 'minSdk = 26');
    // Same key on every build (CI and PC) so a new APK installs over the old one.
    if (!s.contains('tool/debug.keystore')) {
      s = s.replaceFirst('android {',
          'android {\n    signingConfigs {\n        getByName("debug") {\n            storeFile = file("../../tool/debug.keystore")\n        }\n    }');
    }
    if (!s.contains('androidx.car.app:app')) {
      s += '\ndependencies {\n    implementation("androidx.car.app:app:1.4.0")\n}\n';
    }
    return s;
  });
  patch('android/app/build.gradle', (s) {
    s = s.replaceFirst(RegExp(r'minSdk(Version)? [^\n]+'), 'minSdkVersion 26');
    if (!s.contains('androidx.car.app:app')) {
      s += "\ndependencies {\n    implementation 'androidx.car.app:app:1.4.0'\n}\n";
    }
    return s;
  });

  // Native Kotlin sources (MainActivity, MonitorService, BootReceiver, EventLog).
  final ktDir = Directory('android/app/src/main/kotlin/ro/noraz/nauto');
  if (ktDir.existsSync()) {
    for (final f in Directory('tool/android').listSync().whereType<File>()) {
      if (f.path.endsWith('.kt')) {
        f.copySync('${ktDir.path}/${f.uri.pathSegments.last}');
        stdout.writeln('copied ${f.uri.pathSegments.last}');
      }
    }
  }
}
